<div class="relatorio-header"><h1 class="relatorio-titulo">Configurações do Sistema</h1></div><div class="form-card"><form method="post" action="<?=URL_BASE?>/configuracoes/guardar"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf_token)?>"><input type="hidden" name="contexto" value="sistema"><?php foreach(['nome_sistema'=>'Nome do sistema','smtp_host'=>'Servidor SMTP','smtp_porta'=>'Porta SMTP','smtp_usuario'=>'Utilizador SMTP','smtp_senha'=>'Senha SMTP','fuso_horario'=>'Fuso horário','idioma'=>'Idioma padrão','moeda'=>'Moeda','sessao_expiracao'=>'Expiração da sessão (segundos)'] as $k=>$l):?><label><?=htmlspecialchars($l)?></label><input type="<?=$k==='smtp_senha'?'password':'text'?>" name="configuracoes[<?=$k?>]" value="<?=$k==='smtp_senha'?'':htmlspecialchars($configuracoes[$k]??'')?>"><?php endforeach?><button class="btn btn-primary">Guardar</button></form></div>
